/**
 * Aegis SpacetimeDB module — Part C's reducers and rules (auth, phases, atomic claims, claim ownership,
 * seed validation) driving Part A's simulation engine (sim.ts). The bundled seed (seed_data.ts, generated by
 * the data pipeline) is loaded on publish, so the module works without an admin seeding step;
 * `seed_world` can still replace it.
 */
import { ScheduleAt } from 'spacetimedb';
import { t, SenderError, type ReducerCtx } from 'spacetimedb/server';
import db, { simTick } from './schema';
import { parseSeed } from './seed';
import * as S from './sim';
import { SEED } from './seed_data';
import { DATA_SOURCES, applyFixToChecklist, mitigationRows, type MitigationRow } from './insurance';
import * as U from './units';
import * as SC from './scenario';
export default db;
type Context = ReducerCtx<typeof db.schemaType>;

function reject(message: string): never {
  throw new SenderError(message);
}
function requireAdmin(ctx: Context) {
  if (!ctx.db.admin.id.find(0)?.identity.isEqual(ctx.sender)) reject('administrator only');
}
function requireWorker(ctx: Context) {
  if (!ctx.db.admin.id.find(0)?.worker?.isEqual(ctx.sender)) reject('worker only');
}
function getSim(ctx: Context) {
  return ctx.db.sim.id.find(0) ?? reject('simulation not initialized');
}
function requireFire(ctx: Context) {
  if (getSim(ctx).phase !== 'fire') reject('fire phase required');
}

// The stored seed is validated once by seed_world/init; cache the parsed copy (keyed by its JSON).
let seedCache: { json: string; seed: S.Seed } | undefined;
/** The world being played: the current scenario (row 1) if there is one, else the base seed (row 0). */
function storedSeed(ctx: Context): S.Seed {
  const json = ctx.db.worldSeed.id.find(1)?.json ?? ctx.db.worldSeed.id.find(0)?.json ?? reject('seed world first');
  if (seedCache?.json !== json) seedCache = { json, seed: JSON.parse(json) as S.Seed };
  return seedCache.seed;
}
function params(ctx: Context): S.FireParams {
  return storedSeed(ctx).params;
}
function log(ctx: Context, lines: string | string[], tick = getSim(ctx).tick) {
  for (const text of typeof lines === 'string' ? [lines] : lines) if (text) ctx.db.eventLog.insert({ id: 0n, tick, text });
}

// Private engine state: exact sim-minute each resident was pinged (keeps deadlines right across speed changes)
// and each building's cumulative fire exposure (the monotone keyed fire, sim.ts fireSubstep).
type EngineState = { pingedAtMinute: Record<number, number>; exposureHazard: Record<number, number> };
function loadEngineState(ctx: Context): EngineState {
  const json = ctx.db.engineState.id.find(0)?.json;
  const parsed = (json ? JSON.parse(json) : {}) as Partial<EngineState>;
  return { pingedAtMinute: parsed.pingedAtMinute ?? {}, exposureHazard: parsed.exposureHazard ?? {} };
}
function saveEngineState(ctx: Context, world: { pingedAtMinute?: Record<number, number>; exposureHazard?: Record<number, number> }) {
  const row = { id: 0, json: JSON.stringify({ pingedAtMinute: world.pingedAtMinute ?? {}, exposureHazard: world.exposureHazard ?? {} }) };
  if (ctx.db.engineState.id.find(0)) ctx.db.engineState.id.update(row);
  else ctx.db.engineState.insert(row);
}

function load(ctx: Context): S.World {
  return {
    sim: { ...getSim(ctx) },
    buildings: [...ctx.db.building.iter()].map((b) => ({ ...b })),
    people: [...ctx.db.person.iter()].map((p) => ({ ...p })),
    tasks: [...ctx.db.task.iter()].map((x) => ({ ...x })),
    cells: [...ctx.db.fireCell.iter()].map((c) => ({ ...c })),
    ...loadEngineState(ctx),
    protectedBuildingIds: U.protectedIds([...ctx.db.unit.iter()]),
  };
}

// Fire engines: plain copies of the unit rows, stepped once per tick after the fire.
function loadUnits(ctx: Context): U.UnitRow[] {
  return [...ctx.db.unit.iter()].map((u) => ({ ...u })).sort((a, b) => a.id - b.id);
}
function saveUnits(ctx: Context, units: U.UnitRow[]) {
  for (const u of units) ctx.db.unit.id.update(u);
}
/** After an engine step: move the trucks, auto-dispatch to burning buildings, keep the world's protection current. */
function stepUnits(ctx: Context, world: S.World, units: U.UnitRow[], tick: number) {
  const r = U.stepUnits(units, world.buildings, world.sim.minutesPerTick);
  world.protectedBuildingIds = U.protectedIds(units);
  log(ctx, r.events, tick);
  return r.changed;
}

/** Persist an engine step: only the rows the engine reports as changed (cheap subscription traffic). */
function saveStep(ctx: Context, r: S.StepResult, world: S.World) {
  ctx.db.sim.id.update(r.sim);
  for (const c of r.cells) ctx.db.fireCell.id.update(c);
  for (const b of r.buildings) ctx.db.building.id.update(b);
  for (const p of r.people) ctx.db.person.id.update(p);
  for (const x of r.tasksUpdated) ctx.db.task.id.update(x);
  for (const x of r.tasksNew) ctx.db.task.insert({ ...x, id: 0n });
  log(ctx, r.events, r.sim.tick);
  saveEngineState(ctx, world);
}

/** Persist a whole world by diff (used after fast-forward). New tasks get auto-increment ids. */
function saveAll(ctx: Context, world: S.World) {
  const same = (a: unknown, b: unknown) => JSON.stringify(a, (_k, v) => (typeof v === 'bigint' ? v.toString() : v)) === JSON.stringify(b, (_k, v) => (typeof v === 'bigint' ? v.toString() : v));
  if (!same(getSim(ctx), world.sim)) ctx.db.sim.id.update(world.sim);
  for (const b of world.buildings) if (!same(ctx.db.building.id.find(b.id), b)) ctx.db.building.id.update(b);
  for (const p of world.people) if (!same(ctx.db.person.id.find(p.id), p)) ctx.db.person.id.update(p);
  for (const c of world.cells) if (!same(ctx.db.fireCell.id.find(c.id), c)) ctx.db.fireCell.id.update(c);
  for (const x of world.tasks) {
    if (x.id === 0n) ctx.db.task.insert({ ...x, id: 0n });
    else if (!same(ctx.db.task.id.find(x.id), x)) ctx.db.task.id.update(x);
  }
  saveEngineState(ctx, world);
}

function upsertResult(ctx: Context, row: S.ResultRow) {
  if (ctx.db.result.scenario.find(row.scenario)) ctx.db.result.scenario.update(row);
  else ctx.db.result.insert(row);
}
/** End of a run: our result + the same fire without Aegis (so the end screen is ready immediately). */
function writeResults(ctx: Context, world: S.World) {
  const seed = storedSeed(ctx);
  upsertResult(ctx, S.computeResults(world, seed.params, 'with_lantern'));
  if (!ctx.db.result.scenario.find('without_lantern')) upsertResult(ctx, S.runBaseline(seed));
}

function seedWorld(ctx: Context, seed: S.Seed) {
  for (const b of [...ctx.db.building.iter()]) ctx.db.building.id.delete(b.id);
  for (const p of [...ctx.db.person.iter()]) ctx.db.person.id.delete(p.id);
  for (const f of [...ctx.db.fix.iter()]) ctx.db.fix.id.delete(f.id);
  for (const c of [...ctx.db.fireCell.iter()]) ctx.db.fireCell.id.delete(c.id);
  for (const x of [...ctx.db.task.iter()]) ctx.db.task.id.delete(x.id);
  for (const e of [...ctx.db.eventLog.iter()]) ctx.db.eventLog.id.delete(e.id);
  for (const r of [...ctx.db.result.iter()]) ctx.db.result.scenario.delete(r.scenario);
  for (const o of [...ctx.db.taskOwner.iter()]) ctx.db.taskOwner.taskId.delete(o.taskId);
  for (const r of [...ctx.db.buildingProfile.iter()]) ctx.db.buildingProfile.buildingId.delete(r.buildingId);
  for (const r of [...ctx.db.mitigation.iter()]) ctx.db.mitigation.id.delete(r.id);
  for (const u of [...ctx.db.unit.iter()]) ctx.db.unit.id.delete(u.id);
  for (const u of U.freshUnits()) ctx.db.unit.insert(u);
  const w = S.buildWorldFromSeed(seed);
  if (ctx.db.sim.id.find(0)) ctx.db.sim.id.update(w.sim);
  else ctx.db.sim.insert(w.sim);
  for (const b of w.buildings) ctx.db.building.insert(b);
  for (const p of w.people) ctx.db.person.insert(p);
  for (const f of w.fixes) ctx.db.fix.insert(f);
  for (const c of w.cells) ctx.db.fireCell.insert(c);
  for (const b of seed.buildings) {
    const f = (b.features ?? {}) as Record<string, unknown>;
    const str = (k: string) => (typeof f[k] === 'string' ? (f[k] as string) : '');
    ctx.db.buildingProfile.insert({
      buildingId: b.id,
      reachProbability: b.reachProbability ?? (b.referenceFireEtaMin !== undefined && b.referenceFireEtaMin >= 0 ? 1 : 0.1),
      roof: str('roof'), vents: str('vents'), eaves: str('eaves'), windows: str('windows'), siding: str('siding'),
      yearBuilt: typeof f.yearBuilt === 'number' ? Math.max(0, Math.round(f.yearBuilt)) : 0,
      sources: DATA_SOURCES,
    });
    for (const m of mitigationRows(b)) ctx.db.mitigation.insert(m);
  }
  saveEngineState(ctx, {});
  writeScenario(ctx, seed);
  log(ctx, 'World seeded — simulated neighborhood; fire calibrated to the 2025 Eaton Fire; risk from CAL FIRE DINS', 0);
}
/** Row 0 = the base seed (pipeline / admin); row 1 = the current random scenario built from it. */
function storeSeed(ctx: Context, seed: S.Seed, id = 0) {
  const row = { id, json: JSON.stringify(seed) };
  if (ctx.db.worldSeed.id.find(id)) ctx.db.worldSeed.id.update(row);
  else ctx.db.worldSeed.insert(row);
  if (id === 0 && ctx.db.worldSeed.id.find(1)) ctx.db.worldSeed.id.delete(1); // a new base drops the old scenario
}
function baseSeed(ctx: Context): S.Seed {
  return JSON.parse(ctx.db.worldSeed.id.find(0)?.json ?? reject('seed world first')) as S.Seed;
}
/** The public scenario row; the ignition point always follows the world's seed. */
function writeScenario(ctx: Context, seed: S.Seed, meta?: { number: number; label: string; picked: boolean }) {
  const p = seed.params;
  const cells = p.ignition.length ? p.ignition : [0];
  const ignitionX = (cells.reduce((s, c) => s + (c % p.cols), 0) / cells.length + 0.5) * p.cellSize;
  const ignitionY = (cells.reduce((s, c) => s + Math.floor(c / p.cols), 0) / cells.length + 0.5) * p.cellSize;
  const prev = ctx.db.scenario.id.find(0);
  const row = { id: 0, number: meta?.number ?? prev?.number ?? 0, label: meta?.label ?? prev?.label ?? 'Eaton demo', picked: meta?.picked ?? prev?.picked ?? false, ignitionX, ignitionY };
  if (prev) ctx.db.scenario.id.update(row);
  else ctx.db.scenario.insert(row);
}

// ───────────────────────────── lifecycle ─────────────────────────────

export const init = db.init((ctx) => {
  ctx.db.admin.insert({ id: 0, identity: ctx.sender, worker: undefined });
  const seed = parseSeed(JSON.stringify(SEED)); // the pipeline's seed, validated like any other
  storeSeed(ctx, seed);
  writeScenario(ctx, seed, { number: 0, label: 'Eaton demo', picked: false });
  seedWorld(ctx, seed);
  ctx.db.simTick.insert({ scheduledId: 0n, scheduledAt: ScheduleAt.interval(1_000_000n) });
});

// Presence: every connected client (dashboard, phones, the AI worker) is a row; screens show the live count.
export const onConnect = db.clientConnected((ctx) => {
  if (!ctx.connectionId) return;
  const connectionId = ctx.connectionId.toHexString();
  const worker = !!ctx.db.admin.id.find(0)?.worker?.isEqual(ctx.sender);
  const row = { connectionId, identity: ctx.sender, worker, connectedAt: ctx.timestamp };
  if (ctx.db.presence.connectionId.find(connectionId)) ctx.db.presence.connectionId.update(row);
  else ctx.db.presence.insert(row);
});
export const onDisconnect = db.clientDisconnected((ctx) => {
  if (ctx.connectionId) ctx.db.presence.connectionId.delete(ctx.connectionId.toHexString());
});

// ───────────────────────────── admin / worker ─────────────────────────────

export const seed_world = db.reducer({ json: t.string() }, (ctx, { json }) => {
  requireAdmin(ctx);
  let seed: S.Seed;
  try {
    seed = parseSeed(json);
  } catch (error) {
    reject(`Invalid seed: ${(error as Error).message}`);
  }
  storeSeed(ctx, seed);
  writeScenario(ctx, seed, { number: 0, label: 'Eaton demo', picked: false });
  seedWorld(ctx, seed);
});

export const register_worker = db.reducer({ identity: t.identity() }, (ctx, { identity }) => {
  requireAdmin(ctx);
  const admin = ctx.db.admin.id.find(0)!;
  ctx.db.admin.id.update({ ...admin, worker: identity });
  for (const p of [...ctx.db.presence.iter()]) {
    const isWorker = p.identity.isEqual(identity);
    if (p.worker !== isWorker) ctx.db.presence.connectionId.update({ ...p, worker: isWorker });
  }
  log(ctx, 'Worker identity registered');
});

export const set_explanation = db.reducer({ buildingId: t.u32(), text: t.string() }, (ctx, { buildingId, text }) => {
  requireWorker(ctx);
  if (text.length > 2000) reject('explanation exceeds 2000 characters');
  const b = ctx.db.building.id.find(buildingId) ?? reject('building not found');
  ctx.db.building.id.update({ ...b, explanation: text });
});

// ───────────────────────────── dashboard ─────────────────────────────

export const reset_sim = db.reducer((ctx) => {
  seedWorld(ctx, storedSeed(ctx));
});

/**
 * A new world on the same town: random wind, fire start, construction (scored by the CAL FIRE model), residents'
 * needs, with fire arrival and reach re-simulated. number 0 = back to the Eaton demo map. Resets to prep.
 */
export const new_scenario = db.reducer({ number: t.u32() }, (ctx, { number }) => {
  if (number === 0) {
    if (ctx.db.worldSeed.id.find(1)) ctx.db.worldSeed.id.delete(1);
    const base = storedSeed(ctx);
    writeScenario(ctx, base, { number: 0, label: 'Eaton demo', picked: false });
    seedWorld(ctx, base);
    log(ctx, 'Back to the Eaton demo map', 0);
    return;
  }
  const seed = SC.makeScenario(baseSeed(ctx), number);
  storeSeed(ctx, seed, 1);
  writeScenario(ctx, seed, { number, label: `Scenario #${number}`, picked: false });
  seedWorld(ctx, seed);
  log(ctx, `Scenario #${number}: new wind, fire start, construction and residents; Aegis re-scored every building`, 0);
});

/** Prep only: start the fire at map cell (cellX, cellY) instead; fire arrival and reach are re-simulated. */
export const set_ignition = db.reducer({ cellX: t.u32(), cellY: t.u32() }, (ctx, { cellX, cellY }) => {
  if (getSim(ctx).phase !== 'prep') reject('pick the fire start before the fire');
  let seed: S.Seed;
  try {
    seed = SC.withIgnition(storedSeed(ctx), cellX, cellY);
  } catch (e) {
    reject((e as Error).message);
  }
  storeSeed(ctx, seed, 1);
  const prev = ctx.db.scenario.id.find(0);
  const number = prev?.number ?? 0;
  writeScenario(ctx, seed, { number, label: number ? `Scenario #${number}` : 'Eaton demo', picked: true });
  // Keep everything the manager already did (approved fixes, budget): only the fire's start, each building's
  // arrival time and its chance of being reached change.
  const p = seed.params;
  for (const sb of seed.buildings) {
    const b = ctx.db.building.id.find(sb.id);
    if (b) {
      const next = { ...b, fireEtaMin: sb.referenceFireEtaMin ?? -1 };
      ctx.db.building.id.update({ ...next, prepared: S.isPrepared(next, p) });
    }
    const prof = ctx.db.buildingProfile.buildingId.find(sb.id);
    if (prof && sb.reachProbability !== undefined) ctx.db.buildingProfile.buildingId.update({ ...prof, reachProbability: sb.reachProbability });
  }
  log(ctx, 'Fire start picked on the map; Aegis re-ran the fire and re-ranked every building', 0);
});

export const set_phase = db.reducer({ phase: t.string() }, (ctx, { phase }) => {
  if (!['prep', 'fire'].includes(phase)) reject('phase must be prep or fire');
  if (phase === 'prep') {
    seedWorld(ctx, storedSeed(ctx));
    return;
  }
  const world = load(ctx);
  if (world.sim.phase !== 'prep') reject('reset to prep before starting another fire');
  const p = params(ctx);
  saveStep(ctx, S.startFire(world, p, p.fireSeed), world);
});

export const set_speed = db.reducer({ minutesPerTick: t.u32() }, (ctx, { minutesPerTick }) => {
  if (minutesPerTick < 1 || minutesPerTick > 60) reject('minutesPerTick must be 1–60');
  // Fire behaviour and deadlines are in sim-minutes, so nothing else needs recomputing.
  ctx.db.sim.id.update({ ...getSim(ctx), minutesPerTick });
});

/** Pause / resume the fire (the dashboard's pause button). */
export const set_running = db.reducer({ running: t.bool() }, (ctx, { running }) => {
  requireFire(ctx);
  ctx.db.sim.id.update({ ...getSim(ctx), running });
});

/** Skip ahead n ticks instantly (demo deep links / "skip ahead"); same engine steps as the scheduled tick. */
export const advance_ticks = db.reducer({ ticks: t.u32() }, (ctx, { ticks }) => {
  requireFire(ctx);
  if (ticks < 1 || ticks > 500) reject('ticks must be 1–500');
  const p = params(ctx);
  const world = load(ctx);
  const units = loadUnits(ctx);
  const wasRunning = world.sim.running;
  for (let i = 0; i < ticks && world.sim.phase === 'fire'; i++) {
    world.sim.running = true;
    const r = S.stepSimulation(world, p, p.fireSeed);
    log(ctx, r.events, r.sim.tick);
    if (r.ended) break;
    stepUnits(ctx, world, units, r.sim.tick);
  }
  if (world.sim.phase === 'fire') world.sim.running = wasRunning;
  saveAll(ctx, world);
  saveUnits(ctx, units);
  if (world.sim.phase === 'ended') writeResults(ctx, world);
});

export const approve_fix = db.reducer({ fixId: t.u32() }, (ctx, { fixId }) => {
  if (getSim(ctx).phase !== 'prep') reject('fixes can only be approved in prep');
  const fix = ctx.db.fix.id.find(fixId) ?? reject('fix not found');
  if (fix.approved) reject('fix already approved');
  const sim = { ...getSim(ctx) };
  if (fix.costUsd > sim.budgetLeft) reject('insufficient budget');
  const b = { ...(ctx.db.building.id.find(fix.buildingId) ?? reject('building not found')) };
  const f = { ...fix };
  const people = [...ctx.db.person.iter()].filter((x) => x.buildingId === b.id);
  const r = S.applyFix(sim, b, f, people, params(ctx));
  if (r.error) reject(r.error);
  ctx.db.sim.id.update(sim);
  ctx.db.building.id.update(b);
  ctx.db.fix.id.update(f);
  documentFix(ctx, f);
  log(ctx, r.event ?? `Approved ${f.name} for ${b.name}`);
});

/** An approved fix documents the insurance mitigation measure it completes. */
function documentFix(ctx: Context, f: { id: number; name: string; buildingId: number }) {
  const rows: MitigationRow[] = [...ctx.db.mitigation.iter()].filter((m) => m.buildingId === f.buildingId).map((m) => ({ ...m, status: m.status as MitigationRow['status'] }));
  const changed = applyFixToChecklist(rows, f);
  if (changed) ctx.db.mitigation.id.update(changed);
}

/** "Aegis recommends": approve the best-value unapproved fixes that fit the remaining budget. */
export const approve_recommended = db.reducer((ctx) => {
  if (getSim(ctx).phase !== 'prep') reject('fixes can only be approved in prep');
  const p = params(ctx);
  const world = load(ctx);
  const fixes = [...ctx.db.fix.iter()].map((f) => ({ ...f }));
  const lines: string[] = [];
  for (const id of S.recommendFixes(world, fixes, p)) {
    const f = fixes.find((x) => x.id === id)!;
    const b = world.buildings.find((x) => x.id === f.buildingId)!;
    const r = S.applyFix(world.sim, b, f, world.people.filter((x) => x.buildingId === b.id), p);
    if (r.error) continue;
    ctx.db.fix.id.update(f);
    ctx.db.building.id.update(b);
    documentFix(ctx, f);
    lines.push(r.event ?? '');
  }
  ctx.db.sim.id.update(world.sim);
  log(ctx, lines.length ? lines : ['No recommended fixes fit the remaining budget']);
});

export const start_evacuation = db.reducer({ buildingId: t.u32() }, (ctx, { buildingId }) => {
  requireFire(ctx);
  const world = load(ctx);
  const b = world.buildings.find((x) => x.id === buildingId) ?? reject('building not found');
  if (b.evacStarted || ['lost', 'clear'].includes(b.status) || b.residents === 0) reject('building cannot start evacuation');
  const r = S.startEvacuation(world, b.id, params(ctx));
  if (r.error) reject(r.error);
  ctx.db.building.id.update(b);
  for (const p of r.people) ctx.db.person.id.update(p);
  saveEngineState(ctx, world);
  log(ctx, r.events);
});

// ───────────────────────────── residents / worker classification ─────────────────────────────

function reply(ctx: Context, personId: number, choice: string, text: string, worker = false) {
  requireFire(ctx);
  if (!['safe', 'cant_move', 'text', 'needs_medical', 'unclear'].includes(choice) || (!worker && !['safe', 'cant_move', 'text'].includes(choice))) reject('invalid check-in choice');
  if (text.length > 2000) reject('reply exceeds 2000 characters');
  const p = params(ctx);
  const world = load(ctx);
  const person = world.people.find((x) => x.id === personId) ?? reject('person not found');
  if (['out', 'left_behind', 'inside'].includes(person.status)) reject('person cannot reply in current state');
  if (worker && (!person.replyText || person.status !== 'pinged')) reject('no pending text reply');
  const changedTasks: S.TaskRow[] = [];
  let newTask: S.TaskRow | undefined;
  let line = '';
  if (choice === 'text') {
    if (!text.trim()) reject('reply text is empty');
    if (person.status !== 'pinged') reject('text reply requires pending check-in');
    person.replyText = text.trim();
    line = `${person.name} replied: “${person.replyText.slice(0, 80)}”`;
  } else if (choice === 'unclear') {
    // Stays pinged, so the ordinary silent-resident escalation deadline still applies.
    line = `${person.name} replied — unclear, a person will follow up`;
  } else if (choice === 'safe') {
    if (person.status === 'safe') return;
    person.status = 'safe';
    if (!worker) person.replyText = text || "I'm safe"; // button replies are recorded too, so "no reply" means no reply
    for (const x of world.tasks) {
      if (x.personId === person.id && !x.done) {
        x.done = true; // obsolete help task
        changedTasks.push(x);
      }
    }
    line = `${person.name}: “I'm safe”`;
  } else {
    if (person.status === 'safe') reject('resident already safe');
    if (!worker) person.replyText = text || "I can't get out";
    const r = S.applyReply(world, person.id, choice, p);
    if (r.error) reject(r.error);
    changedTasks.push(...r.tasksUpdated);
    newTask = r.task;
    line = r.events[0] ?? `${person.name}: ${choice}`;
  }
  ctx.db.person.id.update(person);
  for (const x of changedTasks) if (x.id !== 0n) ctx.db.task.id.update(x);
  if (newTask) ctx.db.task.insert({ ...newTask, id: 0n });
  for (const b of S.refreshDerived(world, p, person.buildingId)) ctx.db.building.id.update(b);
  log(ctx, line);
}

export const reply_checkin = db.reducer({ personId: t.u32(), choice: t.string(), text: t.string() }, (ctx, a) => reply(ctx, a.personId, a.choice, a.text));

export const set_reply_class = db.reducer({ personId: t.u32(), choice: t.string() }, (ctx, { personId, choice }) => {
  requireWorker(ctx);
  if (choice === 'text') reject('worker must classify text');
  reply(ctx, personId, choice, '', true);
});

// ───────────────────────────── staff ─────────────────────────────

export const claim_task = db.reducer({ taskId: t.u64(), staffName: t.string() }, (ctx, { taskId, staffName }) => {
  requireFire(ctx);
  const name = staffName.trim();
  if (!name || name.length > 80) reject('staff name must be 1–80 characters');
  const task = ctx.db.task.id.find(taskId) ?? reject('task not found');
  if (task.done) reject('task already done');
  if (task.claimedBy !== '') reject(`already claimed by ${task.claimedBy.replace(S.AUTO_SUFFIX, ' (on-site)')}`);
  const person = task.personId ? ctx.db.person.id.find(task.personId) : undefined;
  if (person && ['safe', 'out', 'left_behind'].includes(person.status)) reject('resident no longer needs help');
  ctx.db.task.id.update({ ...task, claimedBy: name });
  ctx.db.taskOwner.insert({ taskId, identity: ctx.sender });
  if (person) ctx.db.person.id.update({ ...person, status: 'claimed' });
  log(ctx, `${name} claimed ${person?.name ?? task.kind}`);
});

/**
 * Aegis's coach: send the building's on-site staff to this resident now instead of waiting out the claim window
 * for a staff phone. The engine then completes the rescue at the building's real staff × van pace (mutual-aid
 * staff for a building with none), exactly like an on-site claim it made itself.
 */
export const assign_staff = db.reducer({ taskId: t.u64() }, (ctx, { taskId }) => {
  requireFire(ctx);
  const task = ctx.db.task.id.find(taskId) ?? reject('task not found');
  if (task.done) reject('task already done');
  if (task.claimedBy !== '') reject(`already claimed by ${task.claimedBy.replace(S.AUTO_SUFFIX, ' (on-site)')}`);
  const person = task.personId ? ctx.db.person.id.find(task.personId) : undefined;
  if (person && ['safe', 'out', 'left_behind'].includes(person.status)) reject('resident no longer needs help');
  const b = ctx.db.building.id.find(task.buildingId) ?? reject('building not found');
  if (b.status === 'lost') reject(`${b.name} is lost`);
  const helper = b.staff > 0 ? b
    : [...ctx.db.building.iter()].filter((x) => x.staff > 0 && x.kind !== 'shelter' && x.status !== 'lost')
      .sort((x, y) => Math.hypot(x.x - b.x, x.y - b.y) - Math.hypot(y.x - b.x, y.y - b.y))[0] ?? b;
  const k = [...ctx.db.task.iter()].filter((x) => x.buildingId === b.id && x.claimedBy.endsWith(S.AUTO_SUFFIX)).length;
  const name = S.onSiteName(helper, k);
  ctx.db.task.id.update({ ...task, claimedBy: name });
  if (person) ctx.db.person.id.update({ ...person, status: 'claimed' });
  log(ctx, `Aegis sent ${name.replace(S.AUTO_SUFFIX, '')} (on-site staff) to ${person?.name ?? b.name}`);
});

export const complete_task = db.reducer({ taskId: t.u64() }, (ctx, { taskId }) => {
  requireFire(ctx);
  const task = ctx.db.task.id.find(taskId) ?? reject('task not found');
  if (!task.claimedBy) reject('claim task first');
  if (!ctx.db.taskOwner.taskId.find(taskId)?.identity.isEqual(ctx.sender)) reject('only the claiming staff member can complete this task');
  if (task.done) reject('task already done');
  const world = load(ctx);
  const x = world.tasks.find((y) => y.id === taskId)!;
  x.done = true;
  ctx.db.task.id.update(x);
  let who = task.kind;
  if (x.personId) {
    const person = world.people.find((y) => y.id === x.personId) ?? reject('person not found');
    if (person.status === 'left_behind') reject('resident cannot be evacuated from a lost building');
    if (!['safe', 'out'].includes(person.status)) person.status = 'out';
    ctx.db.person.id.update(person);
    for (const b of S.refreshDerived(world, params(ctx), person.buildingId)) ctx.db.building.id.update(b);
    who = person.name;
  }
  log(ctx, `${who} reached safety with ${task.claimedBy}`);
});

// ───────────────────────────── fire engines ─────────────────────────────

/** Send a free engine to a building (Aegis's advisor: ahead of the fire, before it ignites). */
export const dispatch_unit = db.reducer({ buildingId: t.u32() }, (ctx, { buildingId }) => {
  requireFire(ctx);
  const units = loadUnits(ctx);
  const b = ctx.db.building.id.find(buildingId) ?? reject('building not found');
  const r = U.dispatch(units, b, b.status !== 'burning', getSim(ctx).minutesPerTick);
  if (r.error || !r.unit) reject(r.error ?? 'no engine free');
  ctx.db.unit.id.update(r.unit);
  log(ctx, r.event!);
});

/** Bring an engine back to staging so it can be sent somewhere else. */
export const release_unit = db.reducer({ unitId: t.u32() }, (ctx, { unitId }) => {
  requireFire(ctx);
  const u = { ...(ctx.db.unit.id.find(unitId) ?? reject('unit not found')) };
  const r = U.release(u);
  if (r.error) reject(r.error);
  ctx.db.unit.id.update(u);
  log(ctx, r.event!);
});

// ───────────────────────────── end of run ─────────────────────────────

export const run_baseline = db.reducer((ctx) => {
  if (getSim(ctx).phase !== 'ended') reject('simulation must end before baseline');
  if (ctx.db.result.scenario.find('without_lantern')) return;
  upsertResult(ctx, S.runBaseline(storedSeed(ctx)));
  log(ctx, 'Without Aegis comparison complete');
});

/** "End & compare": run the rest of the fire instantly, then write both results. */
export const end_and_compare = db.reducer((ctx) => {
  requireFire(ctx);
  const p = params(ctx);
  const world = load(ctx);
  const units = loadUnits(ctx);
  const followed = S.fastForward(world, p, p.fireSeed, {
    followCoach: true,
    // engines still driving in arrive and protect, exactly as they would have in the live run
    afterStep: (w) => { U.stepUnits(units, w.buildings, w.sim.minutesPerTick); w.protectedBuildingIds = U.protectedIds(units); },
  });
  saveAll(ctx, world);
  saveUnits(ctx, units);
  writeResults(ctx, world);
  log(ctx, followed ? `Fast-forwarded to the end of the fire, following Aegis's advice (${followed} more building${followed === 1 ? '' : 's'} evacuated)` : 'Fast-forwarded to the end of the fire', world.sim.tick);
});

export const tick = db.reducer({ onSchedule: simTick }, { arg: simTick.rowType }, (ctx, _args) => {
  const sim = getSim(ctx);
  if (!sim.running || sim.phase !== 'fire') return;
  const p = params(ctx);
  const world = load(ctx);
  // Seeded per fire step (not ctx.random) so the live run and the baseline burn the same fire.
  const r = S.stepSimulation(world, p, p.fireSeed);
  saveStep(ctx, r, world);
  if (r.ended) writeResults(ctx, world);
  else saveUnits(ctx, stepUnits(ctx, world, loadUnits(ctx), r.sim.tick));
});
